#!/usr/bin/env bash
# One box-pushing flight for the 2026-10-17 push-PROFILE campaign: the 10-16 campaign's fly.sh
# (box_pushing_campaign_20261016/tools/fly.sh) with the push profile set explicitly. Everything
# else is the 10-16 final configuration as generated by make_push_pull_yaml.py.
#   fly.sh <tag> [key=val ...]          (clean slate first, in a SEPARATE call)
# Environment:
#   T=20       push_pull_push_time_s [s] (the move, after the 1.5 s settle)
#   RAMP=3     push_pull_push_ramp_s [s]; 0 = the min-snap move flown on 10-16 (then T=24)
#   MASS=0.500 DIST=0.50 MU_S=0.29 MU_K=0.29 BOX_Y0=DIST/2   as on 10-16
#   PL_DRIVER_ARGS adds to the driver's arguments; PEGASUS_PUSH_* pass through.
set -o pipefail
TAG="${1:?tag}"; shift
C="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
P="$C/../push_pull_20261003"
Y=~/ros2_ws/src/fsc_autopilot_ros2/config/params_single_aerial_manipulator_whole_body_l1_4d_direct_actuation_t650_sim_box_pushing.yaml
mkdir -p "$C/runs"
MASS=${MASS:-0.500}; DIST=${DIST:-0.50}; T=${T:-20}; RAMP=${RAMP:-3}
MU_S=${MU_S:-0.29}; MU_K=${MU_K:-0.29}
read Y0 SLOT < <(python3 -c "print(f'{$DIST/2:.4f} {$T+3.0:.2f}')")
Y0=${BOX_Y0:-$Y0}
/usr/bin/python3 "$P/tools/make_push_pull_yaml.py" > /dev/null
ARGS=("push_pull_push_distance=$DIST" "push_pull_push_time_s=$T" "push_pull_push_ramp_s=$RAMP" "$@")   # later args win
LAW=(); for kv in "${ARGS[@]}"; do
  if [[ $kv == push_pull_* ]]; then k=${kv%%=*}; v=${kv#*=}
    # rclcpp refuses an integer for a double parameter and the planner dies at startup
    # (c_nom_1, 2026-10-17: "push_pull_push_time_s: 20") -- write bare integers as floats
    [[ $v =~ ^-?[0-9]+$ ]] && v="$v.0"
    grep -q "^    $k:" $Y || { echo "no planner key $k"; exit 1; }
    sed -i -E "s|^(    $k:)\s*[^#]*(#.*)?$|\1 $v  \2|" $Y; echo "  $k -> $v"
  else LAW+=("$kv"); fi; done
[[ ${#LAW[@]} -gt 0 ]] && /usr/bin/python3 ~/fsc_PegasusSimulator/application/robotic_arm/utils/wb_l1_set_gains.py --file $Y "${LAW[@]}" | grep -- "->"
cp $Y "$C/runs/$TAG.yaml"
{ printf '%s\n' "${ARGS[@]}"; echo "MASS=$MASS"; echo "DIST=$DIST"; echo "T=$T"; echo "RAMP=$RAMP"; echo "MU_S=$MU_S"; echo "MU_K=$MU_K"; echo "BOX_Y0=$Y0"; } > "$C/runs/$TAG.args"
cd "$P" && PL_RUNS_DIR="$C/runs" PUSH_FEEDBACK=${PUSH_FEEDBACK:-raw} PEGASUS_PUSH_BOX_MASS=$MASS \
  PEGASUS_PUSH_FRICTION_STATIC=$MU_S PEGASUS_PUSH_FRICTION_DYNAMIC=$MU_K \
  PEGASUS_PUSH_BOX_XY="${PEGASUS_PUSH_BOX_XY:-1.275,$Y0}" \
  PL_DRIVER_ARGS="--timetable --slot-release $SLOT ${PL_DRIVER_ARGS:-}" \
  bash tools/run_pl.sh $TAG > "$C/runs/$TAG.console.log" 2>&1
/usr/bin/python3 "$P/tools/make_push_pull_yaml.py" > /dev/null
echo "[$TAG] $(grep -E '^completed|^ABORTED' "$C/runs/$TAG.console.log" | head -1 | cut -c1-150)"
